reg [31:0] alu_comb;
reg [31:0] alu_out;
always @(*) begin
    case (funct3)
        3'b000: alu_comb = (opcode == OP_ALUR && alt) ? (a - alu_b) : (a + alu_b);
        3'b001: alu_comb = a << shamt;
        3'b010: alu_comb = ($signed(a) < $signed(alu_b)) ? 32'd1 : 32'd0;
        3'b011: alu_comb = (a < alu_b) ? 32'd1 : 32'd0;
        3'b100: alu_comb = a ^ alu_b;
        3'b101: begin
            if (alt) alu_comb = $signed(a) >>> shamt;
            else     alu_comb = a >> shamt;
        end
        3'b110: alu_comb = a | alu_b;
        3'b111: alu_comb = a & alu_b;
        default: alu_comb = 32'd0;
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) alu_out <= 32'd0;
    else        alu_out <= alu_comb;
